import React, { useEffect, useState } from "react";

export default function ReferralHistoryTable() {
  const [referrals, setReferrals] = useState([]);
  const [filteredReferrals, setFilteredReferrals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    const fetchReferralHistory = async () => {
      setLoading(true);
      setError(null);

      const token = localStorage.getItem("authToken");
      const baseUrl = process.env.REACT_APP_API_BASE_URL?.trim() || "http://localhost:8080";

      try {
        const res = await fetch(`${baseUrl}/api/bonus-history/all-referrals`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error("Failed to fetch referral history");

        const data = await res.json();
        setReferrals(data);
        setFilteredReferrals(data);
      } catch (err) {
        console.error("Error fetching referrals:", err);
        setError(err.message || "Something went wrong");
      } finally {
        setLoading(false);
      }
    };

    fetchReferralHistory();
  }, []);

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return "Invalid Date";
    return date.toLocaleString("en-US", { dateStyle: "medium", timeStyle: "short" });
  };

  const handleFilter = () => {
    const filtered = referrals.filter((ref) => {
      const refDate = new Date(ref.createdAt);
      const start = startDate ? new Date(startDate) : null;
      const end = endDate ? new Date(endDate) : null;

      if (start && refDate < start) return false;
      if (end && refDate > end) return false;
      return true;
    });
    setFilteredReferrals(filtered);
  };

  const totalAmount = filteredReferrals.reduce((sum, ref) => sum + Number(ref.amount), 0);

  return (
    <div className="p-6 bg-gray-50 rounded-lg shadow-md">
      <h2 className="text-2xl font-semibold mb-4 text-gray-800">Referral Bonus History</h2>

      {/* Date Filter */}
      <div className="flex space-x-4 mb-4">
        <div>
          <label className="block text-sm font-medium text-gray-700">Start Date</label>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">End Date</label>
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
          />
        </div>
        <button
          onClick={handleFilter}
          className="mt-6 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
        >
          Filter
        </button>
      </div>

      {loading && (
        <div className="space-y-2">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-8 bg-gray-200 rounded animate-pulse"></div>
          ))}
        </div>
      )}

      {error && <p className="text-red-500 text-center">{error}</p>}

      {!loading && !error && (
        <div className="overflow-x-auto">
          <table className="min-w-full bg-white rounded-lg shadow-md border border-gray-200">
            <thead className="bg-gray-100">
              <tr>
                {["Type", "Amount", "Referrer", "User", "Status", "Created At"].map((header) => (
                  <th
                    key={header}
                    className="px-4 py-3 text-left text-sm font-medium text-gray-700 border-b"
                  >
                    {header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filteredReferrals.length > 0 ? (
                filteredReferrals.map((ref, index) => (
                  <tr key={index} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-2 border">{ref.type || "Referral"}</td>
                    <td className="px-4 py-2 border text-green-600 font-semibold">
                      {Number(ref.amount).toFixed(2)}
                    </td>
                    <td className="px-4 py-2 border">{ref.sourceGameId || "N/A"}</td>
                    <td className="px-4 py-2 border">{ref.userGameId || "N/A"}</td>
                    <td className="px-4 py-2 border">{ref.status || "COMPLETED"}</td>
                    <td className="px-4 py-2 border">{formatDate(ref.createdAt)}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="6" className="text-center py-4 text-gray-500">
                    No referral history found
                  </td>
                </tr>
              )}
            </tbody>
            {filteredReferrals.length > 0 && (
              <tfoot>
                <tr className="bg-gray-100 font-semibold">
                  <td className="px-4 py-2 border">Total</td>
                  <td className="px-4 py-2 border text-green-600">{totalAmount.toFixed(2)}</td>
                  <td colSpan="4" className="border"></td>
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      )}
    </div>
  );
}
